{"relative_path": "factory/temp/factory/infra/validation.py", "function_name": "_blocker_findings_from_risks", "new_function_code": "def _blocker_findings_from_risks(findings: list[ReviewFinding], risks: list[AuditRisk], known_task_ids: set[str]) -> tuple[list[ReviewFinding], list[str]]:
    """Anti-laziness guard for the self-graded red-team verdict.

    The red-team model emits BOTH `findings` (which route re-execution) and
    `risks` (which name offending tasks). A lazy model can emit Critical/High
    `risks` flagging real defects yet leave `findings` empty — which lets
    `red_team_passed` return True and skip re-execution entirely, so the
    defects ship to ops unreviewed.

    Any Critical/High `AuditRisk` that carries a `task_id` inside the approved
    plan but has NO matching blocker `ReviewFinding` is promoted to a blocker
    finding, so the offending task is actually re-coded. Risks that name a
    defect but carry no resolvable `task_id` are returned separately so the
    caller can HARD FAIL them as unresolvable (mirrors the rubric_cube
    global-blocker rule)."""
    blocker_task_ids = _collect_blocker_task_ids(findings)
    augmented = list(findings)
    unresolved_global: list[str] = []
    for r in risks:
        if not _is_significant_risk(r):
            continue
        if not _has_resolvable_task(r, known_task_ids):
            unresolved_global.append(_unresolved_label(r))
            continue
        if r.task_id in blocker_task_ids:
            continue
        augmented.append(_promote_risk_to_finding(r))
        blocker_task_ids.add(r.task_id)
    return (augmented, unresolved_global)


def _collect_blocker_task_ids(findings: list[ReviewFinding]) -> set[str]:
    return {f.task_id for f in findings if f.severity == 'blocker'}


def _is_significant_risk(r: AuditRisk) -> bool:
    return r.severity in ('Critical', 'High')


def _has_resolvable_task(r: AuditRisk, known_task_ids: set[str]) -> bool:
    return bool(r.task_id) and r.task_id in known_task_ids


def _unresolved_label(r: AuditRisk) -> str:
    return r.component or r.task_id or '<anonymous>'


def _promote_risk_to_finding(r: AuditRisk) -> ReviewFinding:
    return ReviewFinding(
        task_id=r.task_id,
        severity='blocker',
        file=r.component,
        line=None,
        message=f'[auto-derived from {r.severity} risk] {r.description}',
        suggestion=r.mitigation,
    )"}
